// 5: conformance vectors
{
  const vectors = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests/packs/vectors.json'), 'utf8')); let bad = 0;
  const { ctx, page } = await open({ errors: errs });
  for (const [ci, c] of vectors.cases.entries()) {
    const lay = c.layers.map((L) => ({ name: L.name, packs: L.packs.map((e) => { const dir = (e.source.match(/collide-[ab]|good/) || [])[0] || c.packs[0]; return entry(dir, { id: e.id, priority: e.priority, source: e.source.startsWith('file:') ? `https://fixtures.test/fx/${dir}/` : e.source }); }) }));
    locks[`v${ci}`] = JSON.stringify({ lock: 1, craftpack: '1.0.0', packs: lay.find((L) => L.name === 'shipped')?.packs || [] });
    const user = lay.find((L) => L.name === 'user')?.packs || [];
    const got = await P(page, async ({ n, user }) => { const mod = await import('/packs.js'); const mem = { v: JSON.stringify({ lock: 1, craftpack: '1.0.0', packs: user }), getItem() { return this.v; }, setItem(k, v) { this.v = v; } };
      const p = mod.createPacks({ shippedLock: `/__lock/v${n}`, storage: mem, search: '' }); await p.ready; await p.loadAll(); const r = p.report(); return { errors: r.errors.map((e) => ({ code: e.code, id: e.id })), warnings: r.warnings.map((w) => ({ code: w.code, kind: w.kind, name: w.name, winner: w.winner, shadowed: w.shadowed })), resolution: r.resolution }; }, { n: ci, user });
    // the loader may add its own diagnostics only for lock problems the vectors do not exercise
    if (JSON.stringify(got) !== JSON.stringify(c.expect)) { bad++; console.log('  vector differs:', c.name, '\n   expected', JSON.stringify(c.expect), '\n   got     ', JSON.stringify(got)); }
  }
  check('conformance: site report equals tests/packs/vectors.json for every case', bad === 0, `${vectors.cases.length} vectors, ${bad} differ`);
  await ctx.close();
}

