  await ctx.addInitScript((l) => { localStorage.getItem('sc.packs.lock') || localStorage.setItem('sc.packs.lock', l); window.__samples = []; window.samples = (m, b) => { window.__samples.push({ keys: Object.keys(m).sort(), b }); }; }, userLock(entry('collide-a'), entry('collide-b')));
